def solve(data):
    # Keep only the greatest revision for each identified event; on ties,
    # the event appearing later in the input wins.
    winners = {}
    selected = []
    for position, event in enumerate(data['events']):
        if 'id' not in event or event['id'] is None:
            selected.append((position, event))
            continue

        key = event['id']
        rank = (event.get('revision', 0), position)
        previous = winners.get(key)
        if previous is None or rank > previous[0]:
            winners[key] = (rank, position, event)

    selected.extend((position, event) for _, position, event in winners.values())
    selected.sort(key=lambda item: item[0])

    balances = {}
    rounding = data.get('rounding', 'half_up')
    for _, event in selected:
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        balances[key] += amount(event, rounding)
    return {'balances': balances}
