from fractions import Fraction


def _fraction(value):
    return Fraction(Decimal(str(value)))


def _round_nonnegative(value, mode):
    quotient, remainder = divmod(value.numerator, value.denominator)
    if mode == 'floor' or mode == 'down':
        return quotient
    if mode == 'up' or mode == 'ceiling':
        return quotient + (remainder != 0)
    return quotient + (2 * remainder >= value.denominator)


def amount(event, mode):
    base = _fraction(event['price']) * _fraction(event.get('quantity', 1))
    discount = _fraction(event.get('discount_bp', 0))
    discount = max(Fraction(0), min(Fraction(10000), discount))
    net = _round_nonnegative(base * (10000 - discount) / 10000, mode)

    tax_bp = _fraction(event.get('tax_bp', 0))
    tax = _round_nonnegative(Fraction(net) * tax_bp / 10000, mode)
    result = net + tax
    if event.get('kind') == 'refund':
        result = -result
    return result
